text:
{
  "title": "استمارة التقديم على الوظيفة وإقرار معالجة البيانات",
  "planted": [
    {
      "slot": "p1",
      "text": "تظل كافة السجلات والبيانات المقدمة من قبل المتقدم محفوظة بشكل حصري في قواعد بيانات شركة النخبة المتقدمة للحلول التقنية، ولا يحق للمتقدم طلب الاطلاع على تلك الملفات أو تعديلها أو مطابقتها بأي شكل من الأشكال بعد إتمام تقديم الطلب، مع احتفاظ الشركة وحدها بحق الاحتفاظ بها أو إتلافها وفقاً لتقديرها الداخلي ودون أدنى مسؤولية."
    },
    {
      "slot": "p2",
      "text": "نقر بأن معالجة البيانات الشخصية للمتقدم تتم بناءً على الموافقة المسبقة والصريحة المقدمة من طرفه عبر تعبئة هذا النموذج، كما يحق للمتقدم سحب هذه الموافقة في أي وقت يشاء، على ألا يخل ذلك بصحة العمليات التي تمت بناءً على تلك الموافقة قبل سحبها، ويُستثنى من ذلك حالات المعالجة اللازمة لتنفيذ التزامات تعاقدية مباشرة أو متطلبات إدارية ملزمة تفرضها طبيعة العمل."
    }
  ],
  "neutral": [
    "تخضع كافة النزاعات الناشئة عن هذه الاستمارة لأنظمة المملكة العربية السعودية، وتختص الجهات القضائية في مدينة الرياض بالفصل فيها وحدها.",
    "تُعتبر حقوق الملكية الفكرية الخاصة بتصميم هذه الاستمارة ومحتواها ملكاً خالصاً لشركة النخبة المتقدمة للحلول التقنية، ولا يحق لأي طرف استنساخها أو استخدامها لأغراض تجارية.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن أي أضرار غير مباشرة أو تبعية قدלhطր للمتقدم نتيجة عدم اكتمال بيانات التقديم أو تأخر الرد.",
    "تبدأ المدة الزمنية لدراسة الطلب فور إرساله إلكترونياً، وتدوم لفترة تقييم تفصيلية تنتهي بإصدار القرار النهائي من إدارة الموارد البشرية.",
    "تُوجه كافة الإشعارات الرسمية والمراسلات المتبادلة بين الطرفين عبر البريد الإلكتروني المسجل في استمارة التقديم ويُعتبر مُبلغاً بها قانونياً."
  ]
